VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'U6', 'Querubín', 4, 5, 'Primer contacto con el balón, enfocado a la diversión y motricidad básica.'),
((SELECT id FROM public.clubs LIMIT 1), 'U7-U8', 'Prebenjamín', 6, 7, 'Descubrimiento guiado del juego, fomento del regate y relación con el balón.'),
((SELECT id FROM public.clubs LIMIT 1), 'U9-U10', 'Benjamín', 8, 9, 'Iniciación al juego colectivo, fomento del pase y control orientado.'),
((SELECT id FROM public.clubs LIMIT 1), 'U11-U12', 'Alevín', 10, 11, 'Desarrollo de los principios tácticos básicos, juego de posesión y fundamentos técnicos.'),
((SELECT id FROM public.clubs LIMIT 1), 'U13-U14', 'Infantil', 12, 13, 'Introducción al fútbol 11. Estructuración espacial y toma de decisiones.'),
((SELECT id FROM public.clubs LIMIT 1), 'U15-U16', 'Cadete', 14, 15, 'Especialización por posiciones, desarrollo del modelo de juego, transiciones rápidas.'),
((SELECT id FROM public.clubs LIMIT 1), 'U17-U19', 'Juvenil', 16, 18, 'Perfeccionamiento táctico, preparación física específica y mentalidad competitiva.'),
((SELECT id FROM public.clubs LIMIT 1), 'Senior', 'Amateur / Primer Equipo', 19, 99, 'Rendimiento y optimización táctica, estrategia operativa (ABP) e intensidad competitiva.')
ON CONFLICT DO NOTHING;

-- Insert Principles (using U15-U16 curriculum as reference for demo)
WITH curr AS (SELECT id FROM public.methodology_curriculum WHERE category_code = 'U15-U16' AND club_id = (SELECT id FROM public.clubs LIMIT 1) LIMIT 1)
INSERT INTO public.methodology_principles (club_id, curriculum_id, name, game_phase, description)
VALUES 
((SELECT id FROM public.clubs LIMIT 1), (SELECT id FROM curr), 'Presión Alta', 'Defensa', 'Recuperar el balón lo más cerca de la portería rival.'),
((SELECT id FROM public.clubs LIMIT 1), (SELECT id FROM curr), 'Salida de Balón', 'Ataque', 'Progresar desde atrás mediante pases cortos y atraer rivales.'),
((SELECT id FROM public.clubs LIMIT 1), (SELECT id FROM curr), 'Transición Defensiva (Tras Pérdida)', 'Transición Ataque-Defensa', 'Presión instantánea al poseedor del balón (Pressing tras pérdida).')
ON CONFLICT DO NOTHING;

