-- U6 (Querubín) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
    categoria_edad, age_category, dificultad, duracion_recomendada, min_players, max_players,
    material, variantes, tags, bloque_sesion, carga_fisica, carga_cognitiva, oposicion, representatividad,
    intensity_level, game_phase, drill_structure, espacio, criterios_exito
) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'El Zoo', 'Juego Lúdico', 'Cada niño con un balón. El entrenador nombra un animal y los niños deben imitarlo conduciendo el balón.', 'Evitar usar las manos, mantener la mirada alta.', ARRAY['Conducción'], ARRAY['Ocupación racional'], ARRAY['querubin'], 'querubin', 1, 10, 6, 15, ARRAY['balones', 'conos'], ARRAY['Sin balón primero'], ARRAY['lúdico', 'conducción'], 'calentamiento', 2, 1, 1, 1, 1, 'general', 'circuit', '20x20m', ARRAY['Todos participan y se divierten']),
((SELECT id FROM public.clubs LIMIT 1), 'Pilla-Pilla con Balón', 'Juego Lúdico', 'Dos "cazadores" sin balón intentan tocar a los demás que conducen su balón. Si te tocan, te quedas congelado.', 'Protección del balón, cambios de dirección.', ARRAY['Conducción', 'Regate'], ARRAY['Percepción'], ARRAY['querubin'], 'querubin', 1, 12, 8, 16, ARRAY['balones', 'petos'], ARRAY['Cazadores con balón'], ARRAY['lúdico', 'percepción'], 'calentamiento', 2, 2, 2, 1, 2, 'general', 'game', '20x20m', ARRAY['No chocar entre compañeros']),
((SELECT id FROM public.clubs LIMIT 1), 'Limpiar la Casa', 'Juego Lúdico', 'Dos equipos divididos por una línea. Hay que lanzar los balones al campo contrario. Gana quien tenga menos.', 'Golpeo con empeine, fuerza.', ARRAY['Pase', 'Golpeo'], ARRAY['Cooperación'], ARRAY['querubin'], 'querubin', 1, 8, 8, 20, ARRAY['muchos balones'], ARRAY['Solo usar pie izquierdo'], ARRAY['golpeo', 'juego'], 'principal', 3, 1, 1, 1, 2, 'general', 'game', '15x15m', ARRAY['Mantener el campo limpio']),
((SELECT id FROM public.clubs LIMIT 1), 'Carrera de Relevos Simple', 'Circuito', 'Conducir hasta un cono, dar la vuelta y pasar el balón al siguiente compañero.', 'Control de la fuerza en la conducción.', ARRAY['Conducción'], ARRAY['Ninguno'], ARRAY['querubin'], 'querubin', 1, 10, 4, 12, ARRAY['balones', 'conos'], ARRAY['Ida pie derecho, vuelta pie izquierdo'], ARRAY['circuito', 'técnica'], 'calentamiento', 2, 1, 1, 1, 2, 'general', 'circuit', '10m', ARRAY['El balón no se escapa más de 1 metro']),
((SELECT id FROM public.clubs LIMIT 1), 'Minipartidos 1v1', 'SSG', 'Partidillos 1 contra 1 en mini-porterías. Muy cortos y rotación constante.', 'Fomentar el atrevimiento, regate y finalización.', ARRAY['Regate', 'Finalización'], ARRAY['1v1 ofensivo'], ARRAY['querubin'], 'querubin', 2, 15, 2, 12, ARRAY['balones', 'miniporterías'], ARRAY['Sin portero, meter gol pasando línea'], ARRAY['1v1', 'finalización'], 'principal', 3, 2, 3, 3, 3, 'attacking_build_up', 'ssg', '10x15m', ARRAY['Atreverse a regatear', 'Tirar a puerta']);

-- U8 (Prebenjamín) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
    categoria_edad, age_category, dificultad, duracion_recomendada, min_players, max_players,
    material, variantes, tags, bloque_sesion, carga_fisica, carga_cognitiva, oposicion, representatividad,
    intensity_level, game_phase, drill_structure, espacio, criterios_exito
) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'El Semáforo', 'Juego Lúdico', 'Conducción libre. Verde: Rápido. Ámbar: Lento. Rojo: Parar pisando el balón.', 'Reacción rápida, balón pegado al pie.', ARRAY['Conducción', 'Control'], ARRAY['Atención'], ARRAY['prebenjamin'], 'prebenjamin', 1, 10, 8, 16, ARRAY['balones'], ARRAY['Cambio de dirección al rojo'], ARRAY['conducción', 'cognitivo'], 'calentamiento', 2, 2, 1, 1, 2, 'general', 'game', '20x20m', ARRAY['Parar rápido al rojo']),
((SELECT id FROM public.clubs LIMIT 1), '1v1 con Dos Porterías', 'SSG', 'Atacante puede marcar en cualquiera de las dos porterías pequeñas. El defensa debe elegir bien cuál cubrir.', 'Uso del engaño (fintas).', ARRAY['Regate'], ARRAY['Toma de decisiones', 'Amplitud'], ARRAY['prebenjamin'], 'prebenjamin', 2, 12, 4, 12, ARRAY['balones', 'conos'], ARRAY['El defensa empieza pasivo'], ARRAY['1v1', 'decisiones'], 'principal', 3, 2, 3, 3, 3, 'attacking_build_up', 'ssg', '15x15m', ARRAY['Buscar la portería vacía']),
((SELECT id FROM public.clubs LIMIT 1), 'Rueda de Pases Simple', 'Analítico', 'Pase al frente y voy a mi derecha (triángulo). Pase y voy donde pasé.', 'Superficie de contacto (interior del pie).', ARRAY['Pase', 'Control'], ARRAY['Movilidad'], ARRAY['prebenjamin'], 'prebenjamin', 1, 10, 3, 9, ARRAY['balones', 'conos'], ARRAY['Control con la otra pierna'], ARRAY['pase', 'técnica'], 'calentamiento', 1, 2, 1, 1, 1, 'general', 'passing_pattern', '5x5m', ARRAY['Pase tenso al pie']),
((SELECT id FROM public.clubs LIMIT 1), '2v2 + Comodín Ofensivo', 'SSG', 'Partido 2 contra 2 con un jugador que siempre ataca. Buscar la ventaja 3v2.', 'Buscar siempre al hombre libre.', ARRAY['Pase'], ARRAY['Superioridad numérica'], ARRAY['prebenjamin'], 'prebenjamin', 2, 15, 5, 10, ARRAY['petos', 'balones'], ARRAY['Limitación de toques al comodín'], ARRAY['2v2', 'superioridad'], 'principal', 3, 3, 3, 3, 3, 'attacking_build_up', 'ssg', '20x20m', ARRAY['Aprovechar el 3v2 para progresar']),
((SELECT id FROM public.clubs LIMIT 1), 'Circuito Técnico-Coordinativo', 'Circuito', 'Zigzag entre picas, salto a vallas y finalización a pequeña portería.', 'Coordinación pies, precisión del tiro.', ARRAY['Conducción', 'Finalización'], ARRAY['Ninguno'], ARRAY['prebenjamin'], 'prebenjamin', 2, 15, 4, 12, ARRAY['picas', 'vallas', 'balones'], ARRAY['Cambiar circuito cada 5 min'], ARRAY['circuito', 'finalización'], 'principal', 2, 1, 1, 1, 2, 'general', 'circuit', '20m', ARRAY['No tirar picas', 'Tiro preciso']);

-- U10 (Benjamín) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
    categoria_edad, age_category, dificultad, duracion_recomendada, min_players, max_players,
    material, variantes, tags, bloque_sesion, carga_fisica, carga_cognitiva, oposicion, representatividad,
    intensity_level, game_phase, drill_structure, espacio, criterios_exito
) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'Rondo 3v1 Clásico', 'Rondo', '3 jugadores mantienen la posesión contra 1 en un cuadrado pequeño.', 'Perfilación corporal, jugar al pie alejado.', ARRAY['Pase', 'Control orientado'], ARRAY['Líneas de pase'], ARRAY['benjamin'], 'benjamin', 2, 12, 4, 12, ARRAY['petos', 'conos'], ARRAY['Máximo 2 toques'], ARRAY['rondo', 'posesión'], 'calentamiento', 2, 2, 2, 2, 2, 'general', 'rondo', '6x6m', ARRAY['Dar al menos 10 pases seguidos']),
((SELECT id FROM public.clubs LIMIT 1), 'Partido 3v3 con Apoyo Lateral', 'SSG', 'Partido 3v3 pero con un comodín en cada banda para centrar. Goles de centro valen doble.', 'Uso de la amplitud, finalización.', ARRAY['Centro', 'Remate'], ARRAY['Amplitud', 'Desdoblamientos'], ARRAY['benjamin'], 'benjamin', 3, 15, 8, 12, ARRAY['petos', 'porterías'], ARRAY['Goles de centro valen doble'], ARRAY['3v3', 'amplitud'], 'principal', 3, 3, 3, 3, 4, 'attacking_build_up', 'ssg', '30x20m', ARRAY['Utilizar las bandas para progresar']),
((SELECT id FROM public.clubs LIMIT 1), 'Duelo 1v1 con Transición', 'SSG', 'Jugador A ataca. Si B roba, hace transición rápida a la otra portería. Si A marca, defiende a C.', 'Agresividad defensiva, velocidad de transición.', ARRAY['Regate', 'Entrada'], ARRAY['Transición defensiva'], ARRAY['benjamin'], 'benjamin', 3, 12, 4, 12, ARRAY['balones', 'porterías pequeñas'], ARRAY['2v1 en transición'], ARRAY['1v1', 'transición'], 'principal', 4, 3, 4, 3, 4, 'transition_def_to_atk', 'ssg', '20x15m', ARRAY['Finalizar rápido tras robo']),
((SELECT id FROM public.clubs LIMIT 1), 'Pase, Control y Tiro', 'Analítico', 'Pase largo, control orientado esquivando pica y tiro a puerta.', 'Orientar el control hacia la portería, no parar el balón.', ARRAY['Control orientado', 'Tiro'], ARRAY['Ninguno'], ARRAY['benjamin'], 'benjamin', 2, 10, 4, 12, ARRAY['picas', 'balones'], ARRAY['Uso de pierna no dominante'], ARRAY['técnica', 'tiro'], 'calentamiento', 2, 1, 1, 1, 2, 'general', 'individual_technical', '25m', ARRAY['Control orientado en un solo toque']),
((SELECT id FROM public.clubs LIMIT 1), 'Partido de 4 Porterías', 'SSG', '3v3. Se puntúa pasando el balón conducido por cualquiera de las 2 mini porterías del rival.', 'Cambio de orientación, buscar espacios libres.', ARRAY['Pase largo'], ARRAY['Cambio de orientación', 'Ocupación de espacios'], ARRAY['benjamin'], 'benjamin', 3, 15, 6, 12, ARRAY['conos', 'petos'], ARRAY['Pase en lugar de conducción'], ARRAY['partido', 'táctica'], 'global', 3, 3, 3, 3, 3, 'attacking_build_up', 'ssg', '25x25m', ARRAY['Circular el balón para mover al rival']);

-- U12 (Alevín) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
    categoria_edad, age_category, dificultad, duracion_recomendada, min_players, max_players,
    material, variantes, tags, bloque_sesion, carga_fisica, carga_cognitiva, oposicion, representatividad,
    intensity_level, game_phase, drill_structure, espacio, criterios_exito
) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'Rondo 4v2', 'Rondo', '4 mantienen contra 2. Buscar pase interior por medio de los dos defensores.', 'Atraer para soltar, ritmo alto de balón.', ARRAY['Pase', 'Control'], ARRAY['Pase interior', 'Tercer hombre'], ARRAY['alevin'], 'alevin', 3, 12, 6, 12, ARRAY['petos'], ARRAY['Obligatorio pase interior para punto extra'], ARRAY['rondo', '4v2'], 'calentamiento', 2, 3, 2, 2, 3, 'attacking_build_up', 'rondo', '8x8m', ARRAY['Conseguir pase entre los dos defensores']),
((SELECT id FROM public.clubs LIMIT 1), 'Juego de Posición 4v4 + 3', 'Posicional', 'Comodines por fuera y uno dentro. Posesión con objetivo de ir de un lado a otro.', 'Perfilación corporal, no estar en la misma línea de pase.', ARRAY['Pase corto', 'Pase largo'], ARRAY['Conservación', 'Progresión'], ARRAY['alevin'], 'alevin', 4, 15, 11, 15, ARRAY['petos', 'conos'], ARRAY['Límite de toques'], ARRAY['posicional', 'juego de posición'], 'principal', 3, 4, 3, 3, 4, 'attacking_build_up', 'positional_game', '25x25m', ARRAY['Encontrar al comodín interior']),
((SELECT id FROM public.clubs LIMIT 1), 'Salida de Balón 4v3', 'Táctico', 'Línea de 4 defensores saca balón contra 3 atacantes que presionan. Objetivo: pasar mediocampo.', 'Amplitud de laterales, mediocentro ofreciendo apoyo.', ARRAY['Pase', 'Conducción'], ARRAY['Salida de balón', 'Superar línea de presión'], ARRAY['alevin'], 'alevin', 3, 15, 7, 14, ARRAY['porterías pequeñas'], ARRAY['Añadir un mediocentro'], ARRAY['salida de balón', 'táctica'], 'principal', 3, 3, 3, 4, 3, 'attacking_build_up', 'ssg', '30x30m', ARRAY['Superar la primera línea de presión']),
((SELECT id FROM public.clubs LIMIT 1), 'Transición 3v2 → 2v1', 'SSG', '3 atacan a 2. Al finalizar, los 2 defensas salen rápido en 2v1 contra el último pasador.', 'Velocidad en el ataque, replegamiento rápido.', ARRAY['Pase al hueco', 'Definición'], ARRAY['Transición rápida', 'Temporización defensiva'], ARRAY['alevin'], 'alevin', 4, 15, 6, 15, ARRAY['porterías'], ARRAY['Obligatorio finalizar en 10 seg'], ARRAY['transición', 'contraataque'], 'principal', 4, 3, 3, 3, 4, 'transition_atk_to_def', 'ssg', '40x30m', ARRAY['No dejar que se arme la defensa']),
((SELECT id FROM public.clubs LIMIT 1), 'Rueda de Pases con Finalización', 'Analítico', 'Circulación: central → lateral → extremo → centro al delantero para remate.', 'Timing del desmarque, tensión del pase.', ARRAY['Centro', 'Remate', 'Pase'], ARRAY['Desmarques de ruptura'], ARRAY['alevin'], 'alevin', 2, 10, 6, 15, ARRAY['conos', 'balones'], ARRAY['Intercambio de posiciones automático'], ARRAY['rueda pases', 'finalización'], 'calentamiento', 2, 2, 1, 2, 2, 'attacking_build_up', 'passing_pattern', 'Medio campo', ARRAY['Remate al primer toque tras centro']);

-- U14 (Infantil) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
    categoria_edad, age_category, dificultad, duracion_recomendada, min_players, max_players,
    material, variantes, tags, bloque_sesion, carga_fisica, carga_cognitiva, oposicion, representatividad,
    intensity_level, game_phase, drill_structure, espacio, criterios_exito
) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'Posicional 6v4 + Portero', 'Posicional', 'Los 6 (línea defensiva + 2 MC) salen jugando ante 4 presionando. Objetivo: dar pase a comodín en campo contrario.', 'Movilidad de los MC, atraer presión para saltar línea.', ARRAY['Pase', 'Control orientado'], ARRAY['Salida lavolpiana', 'Tercer hombre'], ARRAY['infantil'], 'infantil', 4, 18, 11, 15, ARRAY['petos', 'portería'], ARRAY['Comodín debe recibir al espacio'], ARRAY['juego de posición', 'salida balón'], 'principal', 3, 4, 3, 4, 4, 'attacking_build_up', 'positional_game', 'Medio campo', ARRAY['Superar la primera línea de presión 5 veces']),
((SELECT id FROM public.clubs LIMIT 1), 'Oleadas de Presión 3v3', 'Táctico', 'El equipo A inicia posesión, el equipo B sale a presionar en sprint. Si roba, ataca. Al salir el balón, nuevo equipo presiona.', 'Coordinación en la presión, basculación.', ARRAY['Interceptación', 'Entrada'], ARRAY['Pressing alto', 'Basculación'], ARRAY['infantil'], 'infantil', 4, 15, 9, 15, ARRAY['balones', 'porterías pequeñas'], ARRAY['Obligatorio robar en < 6 seg'], ARRAY['presión', 'táctica'], 'principal', 4, 3, 4, 3, 5, 'defending_high_press', 'ssg', '30x20m', ARRAY['Robar balón en zona alta']),
((SELECT id FROM public.clubs LIMIT 1), 'Rondo Móvil 5v2 (2 zonas)', 'Rondo', 'Mantienen 5 contra 2. A los 5 pases, deben transferir el balón a la otra zona y todos se mueven.', 'Velocidad de circulación, reacción a la transición de zona.', ARRAY['Pase corto', 'Pase medio'], ARRAY['Conservación', 'Movilidad'], ARRAY['infantil'], 'infantil', 3, 12, 7, 14, ARRAY['conos', 'petos'], ARRAY['Defensas se cambian cada robo'], ARRAY['rondo', 'posesión'], 'calentamiento', 3, 3, 2, 2, 3, 'attacking_build_up', 'rondo', '15x30m', ARRAY['Conseguir cambiar de zona 3 veces seguidas']),
((SELECT id FROM public.clubs LIMIT 1), 'Finalización tras Centro Lateral', 'Táctico', 'Creación de jugada por banda, 2v1 al lateral, centro al área donde esperan 2 atacantes vs 2 centrales.', 'Timing de remate, ocupación de zonas de remate (1º palo, 2º palo, rechace).', ARRAY['Centro', 'Remate de cabeza', 'Volea'], ARRAY['Desdoblamiento', 'Ocupación área'], ARRAY['infantil'], 'infantil', 3, 15, 8, 16, ARRAY['portería grande'], ARRAY['Añadir mediocentro llegador'], ARRAY['finalización', 'bandas'], 'principal', 2, 3, 3, 4, 3, 'attacking_finishing', 'passing_pattern', 'Zona ataque', ARRAY['Un rematador ataca siempre el primer palo']),
((SELECT id FROM public.clubs LIMIT 1), 'Partido Modificado: Zonas de Riesgo', 'SSG', 'Pérdida en zona de creación (zona central marcada) vale doble para el rival si marcan en transición.', 'Seguridad en el pase, no arriesgar en zonas prohibidas.', ARRAY['Pase de seguridad'], ARRAY['Gestión de riesgo', 'Seguridad defensiva'], ARRAY['infantil'], 'infantil', 4, 20, 14, 22, ARRAY['conos para marcar zonas'], ARRAY['Solo 2 toques en zona de riesgo'], ARRAY['partido', 'táctica'], 'global', 3, 4, 4, 4, 4, 'defending_mid_block', 'ssg', 'Campo entero', ARRAY['0 pérdidas en zona de riesgo']);

-- U16 (Cadete) - 5 exercises
INSERT INTO public.banco_ejercicios (
    club_id, nombre, tipo, descripcion, correcciones, objetivo_tecnico, objetivo_tactico,
