) VALUES 
((SELECT id FROM public.clubs LIMIT 1), 'Juego de Posición 7v7 + 3', 'Posicional', 'Posesión intensa. 3 comodines (2 por fuera, 1 por dentro). Foco en encontrar el tercer hombre.', 'Uso del comodín interior, perfilación ofensiva.', ARRAY['Pase tenso'], ARRAY['Tercer hombre', 'Juego interior'], ARRAY['cadete'], 'cadete', 5, 20, 17, 20, ARRAY['petos'], ARRAY['Si pase a comodín interior, libre toques'], ARRAY['juego posición', 'cadete'], 'principal', 4, 4, 4, 4, 4, 'attacking_build_up', 'positional_game', '40x40m', ARRAY['Encontrar al comodín interior 5 veces']),
((SELECT id FROM public.clubs LIMIT 1), 'Transición Ofensiva Rápida 4v3', 'SSG', 'El entrenador mete balón a zona defensiva. Central despeja a MC, que lanza rápido a 3 delanteros contra 3 defensas.', 'Pase profundo inmediato tras recuperación.', ARRAY['Pase en profundidad'], ARRAY['Transición rápida', 'Contraataque'], ARRAY['cadete'], 'cadete', 4, 15, 8, 16, ARRAY['balones', 'portería'], ARRAY['Limite de tiempo: 8 segundos para finalizar'], ARRAY['contraataque', 'transición'], 'principal', 4, 3, 4, 3, 5, 'transition_def_to_atk', 'passing_pattern', 'Medio campo', ARRAY['Finalizar antes de 8 segundos']),
((SELECT id FROM public.clubs LIMIT 1), 'Automatismo Defensivo: Basculación Línea 4', 'Táctico', 'Línea de 4 defensas más pivote. El rival mueve el balón de lado a lado. Los defensas bascularán sin perder distancias.', 'Distancia entre centrales, laterales cerrando, perfil corporal.', ARRAY['Despeje'], ARRAY['Basculación', 'Cobertura'], ARRAY['cadete'], 'cadete', 4, 15, 10, 15, ARRAY['conos para referencia'], ARRAY['Mover balón más rápido'], ARRAY['defensa', 'línea 4'], 'principal', 2, 4, 2, 4, 3, 'defending_mid_block', 'positional_game', 'Ancho de campo', ARRAY['No perder la estructura de la línea']),
((SELECT id FROM public.clubs LIMIT 1), 'Rondo de Presión 6v2 Intenso', 'Rondo', '2 en el medio presionan a 6 a alta intensidad. Robo o 10 pases cambia los del medio.', 'Presión conjunta, cerrar línea de pase dividiendo.', ARRAY['Pase al primer toque'], ARRAY['Pressing', 'Cerrar líneas de pase'], ARRAY['cadete'], 'cadete', 3, 10, 8, 10, ARRAY['petos'], ARRAY['1 toque obligatorio'], ARRAY['rondo', 'presión'], 'calentamiento', 4, 3, 3, 2, 4, 'defending_high_press', 'rondo', '10x10m', ARRAY['Robar en menos de 5 pases']),
((SELECT id FROM public.clubs LIMIT 1), 'Partido Táctico: Defensa en Bloque Medio', 'SSG', 'El equipo defensor espera en bloque medio. Si el rival entra, se dispara la presión coordinada.', 'Temporización, saltos a la presión coordinados.', ARRAY['Interceptación'], ARRAY['Bloque medio', 'Presión tras gatillo'], ARRAY['cadete'], 'cadete', 5, 25, 22, 22, ARRAY['campo completo'], ARRAY['Puntos dobles por robar en mediocampo'], ARRAY['partido', 'táctica', '11v11'], 'global', 4, 4, 4, 4, 4, 'defending_mid_block', 'positional_game', 'Campo entero', ARRAY['El rival no progresa por el centro']);

