((SELECT id FROM public.clubs LIMIT 1), 'Salida de Balón vs Presión Alta 11v11', 'SSG', 'Equipo A saca de puerta buscando conectar con MC. Equipo B presiona al hombre.', 'Uso del tercer hombre, lateral atrayendo, central fijando.', ARRAY['Pase', 'Control'], ARRAY['Salida de balón', 'Superar presión alta'], ARRAY['juvenil', 'senior'], 'senior', 5, 20, 22, 22, ARRAY['ninguno'], ARRAY['Punto extra si Equipo A llega a mediocampo con balón controlado'], ARRAY['salida balón', '11v11', 'táctica'], 'global', 4, 4, 4, 4, 4, 'attacking_build_up', 'positional_game', 'Campo entero', ARRAY['Superar presión 3 veces seguidas sin pérdida']),
((SELECT id FROM public.clubs LIMIT 1), 'ABP: Córner a Favor (Estrategia)', 'Analítico', 'Ensayo de 3 jugadas de córner (1º palo, 2º palo, corto). Repetición analítica y luego con oposición activa.', 'Timing de desmarque, precisión del lanzador, bloqueos.', ARRAY['Golpeo balón parado', 'Remate de cabeza'], ARRAY['Bloqueos', 'Desmarques'], ARRAY['juvenil', 'senior'], 'senior', 3, 15, 11, 20, ARRAY['balones', 'portería'], ARRAY['Añadir contraataque rival si despejan'], ARRAY['abp', 'córner', 'estrategia'], 'principal', 1, 4, 3, 4, 2, 'set_pieces', 'passing_pattern', 'Área penal', ARRAY['Rematar el 80% de los centros']),
((SELECT id FROM public.clubs LIMIT 1), 'Pressing tras Pérdida: 8v8', 'SSG', 'Posesión 8v8. El equipo que pierde el balón tiene 5 segundos para robar. Si no lo hace, repliega a zona marcada.', 'Reacción inmediata a la pérdida, cerrar primeros pases.', ARRAY['Entrada'], ARRAY['Pressing tras pérdida', 'Cambio de chip'], ARRAY['juvenil', 'senior'], 'senior', 5, 18, 16, 20, ARRAY['petos', 'zonas delimitadas'], ARRAY['Si se roba en 5s y marca, vale x3'], ARRAY['transición', 'pressing'], 'principal', 4, 4, 4, 4, 5, 'transition_atk_to_def', 'positional_game', 'Medio campo', ARRAY['Robar en menos de 5 segundos']),
((SELECT id FROM public.clubs LIMIT 1), 'Ataque Posicional: Hundir Bloque Bajo', 'Táctico', 'Ataque 10v9. El equipo defensor juega en 5-4-1 muy replegado. Objetivo: mover rápido para abrir huecos.', 'Velocidad de circulación, uso de los carrileros, tiros lejanos.', ARRAY['Pase tenso', 'Centro'], ARRAY['Desequilibrio', 'Ataque a bloque bajo'], ARRAY['juvenil', 'senior'], 'senior', 5, 20, 19, 22, ARRAY['balones'], ARRAY['Límite de toques en el centro del campo'], ARRAY['ataque posicional', 'bloque bajo'], 'principal', 3, 4, 4, 4, 4, 'attacking_build_up', 'positional_game', '3/4 campo', ARRAY['Generar tiro claro al menos cada 2 minutos']),
((SELECT id FROM public.clubs LIMIT 1), 'Rueda Alta Intensidad (Calentamiento Senior)', 'Analítico', 'Pase fuerte, dejada de cara, balón largo al espacio y finalización a puerta.', 'Tensión del pase, timing perfecto del desmarque.', ARRAY['Pase largo', 'Dejada de cara'], ARRAY['Tercer hombre analítico'], ARRAY['juvenil', 'senior'], 'senior', 4, 12, 10, 15, ARRAY['conos', 'picas', 'balones'], ARRAY['A un solo toque todo'], ARRAY['calentamiento', 'técnica', 'senior'], 'calentamiento', 3, 3, 1, 2, 3, 'general', 'passing_pattern', '40m', ARRAY['Ningún pase debe ir botando']),
((SELECT id FROM public.clubs LIMIT 1), 'Juego de Posición 5v5+5', 'Posicional', '5 por fuera, 5 dentro y 5 defensores. Mantener posesión jugando siempre por dentro para conectar con los de fuera.', 'Juego interior, visión periférica.', ARRAY['Pase oculto', 'Control orientado'], ARRAY['Juego interior', 'Fijar y descargar'], ARRAY['juvenil', 'senior'], 'senior', 5, 15, 15, 15, ARRAY['petos', 'conos'], ARRAY['Defensa que roba pasa a atacar al instante'], ARRAY['juego de posición', 'posesión'], 'principal', 4, 4, 4, 3, 4, 'attacking_build_up', 'positional_game', '30x30m', ARRAY['Jugar por dentro antes de jugar por fuera']),
((SELECT id FROM public.clubs LIMIT 1), 'ABP: Falta Lateral', 'Analítico', 'Ensayo de falta lateral. Variantes: tiro directo o centro a zonas asignadas. Trabajo de los rechaces.', 'Posición corporal para rematar, segunda jugada.', ARRAY['Tiro libre', 'Remate'], ARRAY['Ocupación racional del área'], ARRAY['juvenil', 'senior'], 'senior', 3, 15, 11, 20, ARRAY['balones'], ARRAY['Defensa en zona vs defensa al hombre'], ARRAY['abp', 'falta'], 'principal', 1, 4, 3, 4, 2, 'set_pieces', 'passing_pattern', 'Área', ARRAY['Ganar la segunda jugada siempre']),
((SELECT id FROM public.clubs LIMIT 1), 'Duelos 1v1, 2v2 y 3v3 Continuos', 'SSG', 'Se juega un 1v1, al finalizar entra un jugador de cada equipo → 2v2, luego 3v3. Alta intensidad.', 'Ganar el duelo individual, transiciones muy rápidas.', ARRAY['Regate', 'Entrada', 'Tiro'], ARRAY['Duelo', 'Coberturas en 2v2'], ARRAY['juvenil', 'senior'], 'senior', 4, 15, 8, 16, ARRAY['balones', 'porterías'], ARRAY['Obligatorio finalizar la jugada rápido'], ARRAY['duelos', 'físico', 'alta intensidad'], 'principal', 4, 3, 4, 2, 5, 'general', 'ssg', '30x20m', ARRAY['Ganar el 60% de los duelos 1v1']),
((SELECT id FROM public.clubs LIMIT 1), 'Circuito Físico-Técnico Intermitente', 'Circuito', 'Posta 1: salto vallas + cabezazo. Posta 2: Sprint 20m + tiro. Posta 3: zigzag + pase tenso.', 'Mantener precisión con fatiga alta.', ARRAY['Pase', 'Tiro', 'Remate cabeza'], ARRAY['Ninguno'], ARRAY['juvenil', 'senior'], 'senior', 3, 20, 10, 20, ARRAY['material diverso', 'balones'], ARRAY['Aumentar distancia del sprint'], ARRAY['físico', 'resistencia', 'técnica'], 'principal', 4, 2, 1, 1, 5, 'general', 'circuit', 'Medio campo', ARRAY['No fallar el gesto técnico por fatiga']),
((SELECT id FROM public.clubs LIMIT 1), 'Partido Modificado: Condicionantes de Zona', 'SSG', 'Campo dividido en 3 zonas. Prohibido dar más de 3 pases en zona de inicio, obligatorio pasar por el centro para atacar.', 'Velocidad en salida, obligar a jugar por dentro.', ARRAY['Pase', 'Control'], ARRAY['Verticalidad', 'Uso del pasillo central'], ARRAY['juvenil', 'senior'], 'senior', 5, 25, 22, 22, ARRAY['conos para marcar zonas'], ARRAY['Gol tras recuperación en zona alta vale doble'], ARRAY['partido modificado', 'táctica global'], 'global', 4, 4, 4, 4, 4, 'general', 'ssg', 'Campo entero', ARRAY['Cumplir las reglas de zona']);
